// ---------- cabana_tronco: cabana de troncos, 1 ou 2 cômodos, fogão a lenha, alpendre, privada ou banheiro, caixa d'água em cavalete ----------
const cbR = (op, k) => criaRng(op.semente == null ? 1 : op.semente, 'cb:' + k)();
