// ---------- barraca_camping: lote de camping com 1 a 4 barracas (iglu ou túnel), fogueira, fogareiro com botijão pequeno, coolers e varal; sem paredes nem rede elétrica ----------
IT([
  ['saco_dormir', 'saco_dormir', 0.65, 1.95, 0.12, { plano: true }], ['colchonete', 'colchonete', 0.6, 1.9, 0.04, { plano: true }],
  ['fogueira', 'fogueira', 1.1, 1.1, 0.35, { janela: false }], ['mesa_camping', 'mesa_camping', 1.2, 0.6, 0.7], ['cadeira_camping', 'cadeira_camping', 0.55, 0.55, 0.85, { janela: false }],
  ['cooler', 'cooler', 0.6, 0.4, 0.4], ['lampiao_camping', 'lampiao', 0.25, 0.25, 0.35, { janela: false }], ['fogareiro', 'fogareiro', 0.45, 0.35, 0.15, { baixo: true }], ['botijao_camping', 'botijao_camping', 0.2, 0.2, 0.3],
]);
const cpR = (op, k) => criaRng(op.semente == null ? 1 : op.semente, 'cp:' + k)();
const CP_VEXT = { 1: 1.15, 2: 1.75, 3: 2.35, 4: 2.95 }, CP_DEPTH = 2.4, CP_ALT = { domo: { 1: 1.1, 2: 1.25, 3: 1.4, 4: 1.5 }, tunel: { 1: 1.0, 2: 1.15, 3: 1.3, 4: 1.4 } };
function cpCfg(op) {
  op = op || {};
  const n = [1, 2, 3, 4].includes(op.barracas) ? op.barracas : 2 + Math.floor(cpR(op, 'n') * 3);
  const tipoOp = ['domo', 'tunel'].includes(op.tipo) ? op.tipo : null;
  const barracas = [];
  for (let i = 0; i < n; i++) barracas.push({ pessoas: 1 + Math.floor(cpR(op, 'p' + i) * 4), tipo: tipoOp || (cpR(op, 't' + i) < 0.5 ? 'domo' : 'tunel') });
  return { n, barracas };
}
// duas colunas de barracas (esquerda e direita) com o corredor de entrada no meio; portas voltadas para o corredor; fogueira ao fundo
function cpLayout(w, d, op) {
  const c = cpCfg(op), cols = [[], []], cur = [0.8, 0.8], out = [];
  c.barracas.forEach((b, i) => {
    const k = i % 2, ve = CP_VEXT[b.pessoas], v0 = cur[k];
    const r = k === 0 ? [0.6, v0, 0.6 + CP_DEPTH, v0 + ve] : [w - 0.6 - CP_DEPTH, v0, w - 0.6, v0 + ve];
    cur[k] = v0 + ve + 0.9; cols[k].push(r);
    out.push(Object.assign({ id: 'barraca' + (i + 1), r, lado: k === 0 ? 'dir' : 'esq', altura: CP_ALT[b.tipo][b.pessoas] }, b));
  });
  const vEnd = Math.max(...out.map(t => (t.r[1] + t.r[3]) / 2)) + 0.5;
  return { tendas: out, vEnd: r2(vEnd), vMax: Math.max(cur[0], cur[1]) - 0.9 };
}
