        for (let i = 0; i < nv; i++) { const r = colocaChao(com, 'vaso_chao', rng); if (r) add(mk(com, 'vaso_chao', r, [0, 1])); }
        // R64: abajur sobre criado-mudo ou cômoda baixa (quarto, sala), com a pegada de verdade (cúpula 0,36 m) afastada das paredes: o renderizador usa este item em vez de inventar o seu
