            const sx = (A[2] - A[0] - it.w) / 2, sz = (A[3] - A[1] - it.d) / 2; // folga do tampo; o abajur vai para o lado oposto da parede mais próxima
            const cx = m.x + (A[0] - R[0] < R[2] - A[2] ? sx : -sx), cz = m.z + (A[1] - R[1] < R[3] - A[3] ? sz : -sz);
