        const cx = p.u + n[0] * (MARG + 0.05 + dp / 2), cz = p.v + n[1] * (MARG + 0.05 + dp / 2);
        const inners = partesUteis(com, 0), solidos = doComodo(com).filter(m => m !== ref && !m.plano && !m.sobre && (!m.decor || m.montagem === 'chao')).map(m => m._r).concat(extraSol[com.id] || []);
        for (const dl of DLS) {
          const c2 = p.eixo === 'u' ? [cx + dl, cz] : [cx, cz + dl], r = [c2[0] - eu / 2, c2[1] - ev / 2, c2[0] + eu / 2, c2[1] + ev / 2];
          if (!dentroUniao(r, inners) || solidos.some(o => sobrepoe(r, o)) || outrasZonas.some(z => sobrepoe(r, z)) || !p.zonas.some(z => sobrepoe(r, z, 0.01))) continue; // a barricada precisa tapar a zona da porta
          H.setIgnora(new Set([...bloq, p.id]));
          const livre = conexo(H.gradeDe(com), solidos.concat([r]), com.externo ? 0.12 : RAIO_JOG);
          H.setIgnora(bloq);
          if (!livre) continue;
          return { r, f };
        }
        return null;
