const TEMP_QUENTE = [0xffd49a, 0xffdca8, 0xffe2b4], TEMP_NEUTRA = [0xfff0d8, 0xfff6e8, 0xf8f4ec], TEMP_FRIA = [0xeaf2ff, 0xf4f8ff];
