    if (B.Cc.length) g.setAttribute('color', new THREE.Float32BufferAttribute(B.Cc, 3)); g.setIndex(B.I); g.computeBoundingSphere(); g.computeBoundingBox();
    const m = new THREE.Mesh(g, B.mat); m.castShadow = !B.mat.transparent; m.receiveShadow = true; m.renderOrder = B.mat.transparent ? 2 : 0; m.name = 'carros/' + B.pai;
    (grupos[B.pai] || (grupos[B.pai] = new THREE.Group())).add(m);
