        if (ext < 0.03 && cls !== "placa") { stats.podadas++; return; }
        var A = acc[cls], a0 = Math.min(gr.start, tot), n0 = Math.min(gr.count, tot - a0); n0 -= n0 % 3; if (n0 < 3) return;
        if (S.dbg) S.dbg.push({ cls: cls, t: n0 / 3, ext: +ext.toFixed(2), tipo: geo.type, par: geo.parameters ? Object.keys(geo.parameters).length : 0, pos: tmp.getCenter(new TH.Vector3()).toArray().map(function (x) { return +x.toFixed(2); }).join(','), sz: tmp.getSize(new TH.Vector3()).toArray().map(function (x) { return +x.toFixed(2); }).join('x'), mat: mat.color.getHexString() });
        var cc = corClasse(mat, cls, primaria, corP, col);
