          if (na) { v.fromBufferAttribute(na, vi).applyMatrix3(nm).normalize(); A.N.push(v.x, v.y, v.z); } else A.N.push(0, 1, 0);
          var cr = cc.r, cg = cc.g, cb = cc.b;
