      if (e && (e.r + e.g + e.b) > 0.05) { out.copy(e).multiplyScalar(Math.max(1, ei) * 1.0); out.r = Math.min(out.r, 1); out.g = Math.min(out.g, 1); out.b = Math.min(out.b, 1); return out; }
      return out.copy(mat.color);
