      res.L = +sz.z.toFixed(3); res.W = +sz.x.toFixed(3); res.H = +sz.y.toFixed(3);
      var ct = contar(grupo); res.tris = ct.tris; res.drawCalls = ct.drawCalls;
      res.danificaveis = danif; res.grupo = grupo;
      grupo.userData.danificaveis = danif; grupo.userData.k = k; grupo.userData.qualidade = q; grupo.userData.dim = { L: res.L, W: res.W, H: res.H };
