// Bala contra o mundo: marcha na grade de 0,25 m até bater em algo mais alto que a bala
function worldRay(ox, oy, oz, dx, dy, dz, maxD) {
  const step = 0.25;
  for (let t = 0.3; t < maxD; t += step) {
    const x = ox + dx * t, y = oy + dy * t, z = oz + dz * t;
    if (y < 0) return { t, x, y: 0, z, kind: 0 };
    const c = cellOf(x, z);
    if (c < 0) return { t, x, y, z, kind: 1 };
    if (occ[c] && y < occH[c]) return { t, x, y, z, kind: occ[c] };
  }
  return null;
}

