  const hd=grp(0,.8,.01,0,tor);hd.rotation.x=human?0:-lean*.6+(R()-.5)*.3;hd.rotation.z=human?0:(R()-.5)*.5;
  mesh(G.head,ms,hd,0,.02,0,.95,1.1,1.02);mesh(G.joint,ms,hd,0,-.06,.03,.08,.05,.08);
