  const f=new T.Mesh(new T.SphereGeometry(1,12,9),M(c,{roughness:.6,metalness:.3}));f.scale.set(1.3,1.2,2.4);f.position.set(0,1.1,0);f.rotation.z=.5;f.castShadow=true;g.add(f);
