  const night=HORA==='noite';
  // terreno: planície do parque, subindo para a Serra do Corvo atrás
  const hf=(x,z)=>{const kx=Math.max(0,Math.abs(x)-64),kz=Math.max(0,-56-z);const k=Math.hypot(kx,kz);return k*.1+Math.max(0,-z-70)*.32+(Math.sin(x*.09)*Math.cos(z*.07)*1.6+Math.sin(x*.23+z*.17)*.5)*Math.min(1,k/8);};
