      const x0 = Math.min(p0[0], p1[0]) - (alongU ? 0 : t / 2), x1 = Math.max(p0[0], p1[0]) + (alongU ? 0 : t / 2), z0 = Math.min(p0[1], p1[1]) - (alongU ? t / 2 : 0), z1 = Math.max(p0[1], p1[1]) + (alongU ? t / 2 : 0);
      const e0 = ext && alongU && s0 < 0.01 ? t / 2 : 0, e1 = ext && alongU && s1 > L - 0.01 ? t / 2 : 0; // fecha o canto externo
