  b.porta = addDoor(X(w / 2), Z(0), 'x', 1.0, b);
  par(0, d, w, d, ['cozinha', 'fora'], [[0.95, 0.9, 'porta']].concat(jns('u', d, [[2.4, 1.0, 'janela', 1.1, 2.1], [uc + (w - uc) / 2, 1.4, 'janela', 1.2, 2.2]])), true);
  b.fundos = addDoor(X(0.95), Z(d), 'x', 0.9, b);
  par(0, 0, 0, d, ['sala', 'fora'], jns('v', 0, [[2.5, 1.2, 'janela'], [7.6, 1.0, 'janela', 1.1, 2.1]]), true);
