// câmera de ombro dentro de casa: não sobe acima do teto nem passa pela parede (corrige a posição que o 70-hud calculou)
let camPrimeira = false;
function camCasa(x, z) { for (const b of FLOORS) if (x > b.x && x < b.x + b.w && z > b.z && z < b.z + b.d) return b; return null; }
{
  const cu = cameraUpdate, _cp = new THREE.Vector3();
  cameraUpdate = function (dt) {
    cu(dt);
    gunGroup.visible = true; camPrimeira = false; // em primeira pessoa a arma some (colada na câmera ela tapa a tela)
    if (!player.alive || CAR.on || ROOF.on || andaresCamAtivo()) return; // casa de andares: câmera vem de 46-andares-jogo
    const b = camCasa(player.x, player.z); if (!b) return;
    const teto = Math.floor((player.y + 0.3) / 3) * 3 + Math.min(b.h, 3) - 0.3;
    const ox = player.x, oy = Math.min(player.y + 1.55, teto), oz = player.z, c = camera.position;
    _cp.set(c.x, Math.min(c.y, teto), c.z);
    // anda da cabeça até a câmera e para antes da primeira parede ou da borda da casa
    const dx = _cp.x - ox, dy = _cp.y - oy, dz = _cp.z - oz, L = Math.hypot(dx, dy, dz), m = 0.18;
    let t = 0;
    for (let s = 0.05; s <= L; s += 0.05) {
      const x = ox + dx * s / L, y = oy + dy * s / L, z = oz + dz * s / L;
      if (solidAt(x, z, y) || x < b.x + m || x > b.x + b.w - m || z < b.z + m || z > b.z + b.d - m) break;
      t = s;
    }
    t = Math.max(0, t - 0.12);
    if (L > 1e-3 && (t < L - 1e-3 || c.y > teto)) {
      // sem espaço atrás do ombro (encostado na parede): vira primeira pessoa, olhos um pouco à frente da cabeça
      if (t < 0.7) { const fx = -Math.sin(view.yaw), fz = -Math.cos(view.yaw); c.set(ox + fx * 0.22, Math.min(player.y + (player.crouch ? 1.15 : 1.6), teto), oz + fz * 0.22); camPrimeira = true; }
      else c.set(ox + dx * t / L, oy + dy * t / L, oz + dz * t / L);
      // em primeira pessoa olha reto pela mira, sem o desvio do ombro (era o que punha a mão do lado esquerdo da tela)
      if (camPrimeira) { const cy = Math.cos(view.pitch); camera.lookAt(c.x - Math.sin(view.yaw) * cy * 10, c.y - Math.sin(view.pitch) * 10, c.z - Math.cos(view.yaw) * cy * 10); } else camera.lookAt(camTarget);
    }
  };
}

