    const y = c.b.h - 0.08 - 0.12, w = c.x1 - c.x0, d = c.z1 - c.z0, e = 0.09, k = 0xe4e0d6;
    cx('reboco', (c.x0 + c.x1) / 2, y, c.z0 + e / 2, w, 0.12, e, k); cx('reboco', (c.x0 + c.x1) / 2, y, c.z1 - e / 2, w, 0.12, e, k);
