      const pts = []; for (const lx of [-m.w / 2, m.w / 2]) for (const lz of [lz0, lz1]) pts.push([m.x + lx * cs + lz * sn, m.z - lx * sn + lz * cs]);
      return [Math.min(...pts.map(p => p[0])), Math.min(...pts.map(p => p[1])), Math.max(...pts.map(p => p[0])), Math.max(...pts.map(p => p[1]))];
