// ----- por quadro: peças do SDK, ligação loot <-> gaveta/armário que abre, tábuas, LOD -----
const _c3v = new THREE.Vector3(), _c3f = new THREE.Vector3();
function c3Atualiza(dt) {
  const agora = performance.now();
  if (C3J.assento && (!player.alive || player.grabbedBy >= 0)) c3Levanta();
  c3LuzesAtualiza();
  const noite = nightF > 0.3; if (C3J.noite !== noite) { C3J.noite = noite; C3D.definirNoite(noite); }
  for (const H of C3J.casas) {
    if (H.lod >= 2) continue;
    H.casa.atualiza(dt, agora, _c3f.set(player.x, player.y + 1, player.z)); // foco: as plantas se curvam ao redor do jogador (o LOD é do jogo)
    for (const cn of H.conts) { // armário ou gaveta do loot abre enquanto a lista está aberta
      const alvo = (typeof openCont !== 'undefined' && openCont && openCont.ref === cn) ? 1 : 0;
      if (Math.abs(alvo - cn.t) > 1e-3 && cn.partes.length) { cn.t += (alvo - cn.t) * Math.min(1, dt * 8); if (Math.abs(alvo - cn.t) < 0.02) cn.t = alvo; for (const id of cn.partes) { const p = H.casa.partes[id]; if (p) p.abre(cn.t); } }
    }
    for (const d of H.portas) { // tábuas do SDK enquanto a barricada original está inteira; depois, as do jogo (plankMesh)
      const p = H.casa.partes['tabuas:' + d.palId]; if (!p || !p.grupo) continue;
      const v = d.planks > 0 && d.planks === d.planks0 && !d.broken && !d.open;
      if (p.grupo.visible !== v) p.grupo.visible = v;
    }
  }
  if (agora - C3J.abreT >= 400) { C3J.abreT = agora; for (const H of C3J.casas) if (H.reg && H.reg === ANDARES.casaP) c3ZumbisAbrem(H); }
  if (agora - C3J.lodT >= 300 || dt === 0 && C3J.lodT === 0) { C3J.lodT = agora; c3Lod(); } // em tempo real: o orçamento de draw calls não espera o relógio do jogo
}
// orçamento de draw calls de todas as casas: as mais perto ficam completas, depois sem peças pequenas, por fim viram caixa com telhado (uma malha só para todas)
// ----- orçamento de draw calls (teto do jogo: 400 por quadro, contando as sombras) -----
// Custo de uma casa por nível: LOD 0 conta duas vezes (o sol desenha a sombra dela), LOD 1 sem as peças pequenas, LOD 2 é só o proxy. O que não é casa (mundo, zumbis, efeitos)
// sai do último quadro: custo medido menos o que as casas custavam no nível em que estavam, suavizado. As casas mais perto escolhem primeiro e dividem o que sobra.
const C3_K0 = 1.8;
