// ===== Assar o corpo do Bestiário numa malha instanciável (osso, pivô e cor por vértice) =====
const BAKE_NEUTRO = { lean: 0, armL: 0, armR: 0, elbL: 0, elbR: 0, legL: 0, legR: 0, kneeL: 0, kneeR: 0, headX: 0, headZ: 0, drop: 0, armOut: 0, neck: 0, headFwd: 0 };
const _bv = new THREE.Vector3();
function bakeBody(spec, lod) {
  BEST.setLOD(lod);
  const root = spec.retrato ? buildRetrato(spec.retrato) : BEST.build(Object.assign({}, spec, { pose: Object.assign({}, BAKE_NEUTRO, spec.pose || {}) })); // retrato: corpo detalhado dos sobreviventes (31-retrato.js)
  const rig = root.userData.rig, P = rig.P;
  rig.fig.position.y = 0; rig.upper.rotation.set(0, 0, 0); rig.headG.rotation.set(0, 0, 0);
  for (const a of rig.arms) { a.g.rotation.set(0, 0, 0); a.el.rotation.set(0, 0, 0); }
  for (const l of rig.legs) { l.g.rotation.set(0, 0, 0); l.kn.rotation.set(0, 0, 0); }
  root.updateMatrixWorld(true);
  const wp = o => o.getWorldPosition(new THREE.Vector3()).toArray();
  // grupo do rig -> [osso, pivô, pivô do pai]
  const B = new Map();
  B.set(rig.headG, [1, wp(rig.headG), [0, 0, 0]]);
  for (const a of rig.arms) { const sh = wp(a.g); B.set(a.g, [a.s < 0 ? 2 : 3, sh, [0, 0, 0]]); B.set(a.el, [a.s < 0 ? 7 : 8, wp(a.el), sh]); }
  for (const l of rig.legs) { const hp = wp(l.g); B.set(l.g, [l.s < 0 ? 4 : 5, hp, [0, 0, 0]]); B.set(l.kn, [l.s < 0 ? 9 : 10, wp(l.kn), hp]); }
  const tronco = [0, [0, 0.9 * P.s, 0], [0, 0, 0]];
  const parts = [], topM = spec.retrato ? null : BEST.topM();
  root.traverse(o => {
    if (!o.isMesh || !o.geometry || o.material.transparent) return;
    for (let p = o; p; p = p.parent) if (!p.visible) return;
    let tag = tronco; for (let p = o.parent; p; p = p.parent) if (B.has(p)) { tag = B.get(p); break; }
    let bone = tag[0], pv = tag[1], pp = tag[2];
    if (o.userData.bone === 11) { bone = 11; pv = B.get(rig.headG)[1]; pp = [0, 0, 0]; }
    const eye = !!o.userData.eye, c = o.material.color;
    const mat = eye ? 3 : o.material === topM ? 1 : 6;
    if (eye && bone === 1) bone = 6;
    const g = o.geometry.clone(); g.applyMatrix4(o.matrixWorld);
    // sangue (mancha/filete/gota): sem polygonOffset na malha assada, então sobe 6 mm pela normal (não some dentro da camisa) e a cor sai mais viva
    const blood = o.material.polygonOffset && o.material.isMeshStandardMaterial;
    if (blood) { const pa = g.attributes.position, na = g.attributes.normal, k = lod < 0.6 ? 0.012 : 0.006; for (let i = 0; i < pa.count; i++) pa.setXYZ(i, pa.getX(i) + na.getX(i) * k, pa.getY(i) + na.getY(i) * k, pa.getZ(i) + na.getZ(i) * k); }
    if (eye) { const k = lod < 0.6 ? 1 : 0.68; g.computeBoundingBox(); const c = g.boundingBox.getCenter(new THREE.Vector3()); g.translate(-c.x, -c.y, -c.z); g.scale(2.2 * k, 2.2 * k, 1.4 * k); g.translate(c.x, c.y, c.z); } // olho legível de longe
    // sangue sempre vermelho-vinho legível, qualquer decay ou camisa
    parts.push({ g, bone, pv, pp, col: blood ? [Math.max(c.r * 1.7, 0.3), Math.min(c.g * 1.7, 0.04), Math.min(c.b * 1.7, 0.04), mat] : [c.r, c.g, c.b, mat] });
  });
  // junta tudo, indexado (cada vértice roda o shader uma vez)
  let nv = 0, ni = 0;
  for (const p of parts) { nv += p.g.attributes.position.count; ni += p.g.index ? p.g.index.count : p.g.attributes.position.count; }
  const pos = new Float32Array(nv * 3), nor = new Float32Array(nv * 3), vc = new Float32Array(nv * 4), bo = new Float32Array(nv), pvA = new Float32Array(nv * 3), ppA = new Float32Array(nv * 3);
  const idx = nv > 65535 ? new Uint32Array(ni) : new Uint16Array(ni);
  let vo = 0, io = 0;
  for (const p of parts) {
    const n = p.g.attributes.position.count;
    pos.set(p.g.attributes.position.array, vo * 3); nor.set(p.g.attributes.normal.array, vo * 3);
    for (let k = 0; k < n; k++) { vc.set(p.col, (vo + k) * 4); bo[vo + k] = p.bone; pvA.set(p.pv, (vo + k) * 3); ppA.set(p.pp, (vo + k) * 3); }
    if (p.g.index) { const a = p.g.index.array; for (let k = 0; k < a.length; k++) idx[io++] = a[k] + vo; }
    else for (let k = 0; k < n; k++) idx[io++] = vo + k;
    vo += n; p.g.dispose();
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.BufferAttribute(pos, 3)); out.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  out.setAttribute('vcol', new THREE.BufferAttribute(vc, 4)); out.setAttribute('bone', new THREE.BufferAttribute(bo, 1));
  out.setAttribute('pivot', new THREE.BufferAttribute(pvA, 3)); out.setAttribute('ppivot', new THREE.BufferAttribute(ppA, 3));
  out.setIndex(new THREE.BufferAttribute(idx, 1)); out.computeBoundingSphere();
  return { geo: out, s: P.s, bulk: P.bulk, verts: nv };
}

