// ===== Frota da Garagem v3 "assada": malha simplificada com cor, rugosidade, metal e luz por vértice =====
// Gerada offline do core.js + frota-*.js (veiculos/garagem-v3) pelo veh/ext.mjs e veh/simp.mjs. Eixos da garagem: +x frente.
const _b64 = s => Uint8Array.from(atob(s), ch => ch.charCodeAt(0)).buffer;
function frotaGeo(L, withAttr) {
  const g = new THREE.BufferGeometry(), p = new Int16Array(_b64(L.pos)), P = new Float32Array(p.length);
  for (let i = 0; i < p.length; i++) P[i] = p[i] * L.s;
  g.setAttribute('position', new THREE.BufferAttribute(P, 3));
  g.setIndex(new THREE.BufferAttribute(L.big ? new Uint32Array(_b64(L.idx)) : new Uint16Array(_b64(L.idx)), 1));
  if (withAttr) { g.setAttribute('vrm', new THREE.BufferAttribute(new Uint8Array(_b64(L.col)), 4, false)); g.computeVertexNormals(); }
  return g;
}
function frotaMaterial() {
  const m = new THREE.MeshPhysicalMaterial({ roughness: 1, metalness: 1, clearcoat: 0.7, clearcoatRoughness: 0.12, side: THREE.DoubleSide });
  m.onBeforeCompile = sh => {
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nattribute vec4 vrm; varying vec3 vCor; varying vec3 vRM;')
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        vCor = vrm.rgb / 255.; float b = vrm.a; vRM = vec3(mod(b, 16.) / 15., mod(floor(b / 16.), 4.) / 3., floor(b / 64.));`);
    sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nvarying vec3 vCor; varying vec3 vRM; uniform float uLuz;')
      .replace('vec4 diffuseColor = vec4( diffuse, opacity );', 'vec4 diffuseColor = vec4( vCor, opacity );')
      .replace('#include <roughnessmap_fragment>', 'float roughnessFactor = max(0.12, vRM.x);')
      .replace('#include <metalnessmap_fragment>', 'float metalnessFactor = vRM.y;')
      .replace('#include <emissivemap_fragment>', 'totalEmissiveRadiance = vCor * vRM.z * uLuz;');
    sh.uniforms.uLuz = m.userData.luz;
  };
  m.userData.luz = { value: 0.6 };
  return m;
}
const FROTA_VIDRO = new THREE.MeshStandardMaterial({ color: 0x1a2430, roughness: 0.05, metalness: 0.6, transparent: true, opacity: 0.55, depthWrite: false, side: THREE.DoubleSide });

// carros das ruas: cada carro de PROPS.cars ganha um modelo da garagem; as caixas antigas viram só dado (matriz e cor, que o carro e as explosões já atualizam)
const FROTA_RUA = ['popular', 'seda', 'suvc', 'strada', 'fusca', 'taxi', 'van', 'hatch', 'ambulancia', 'viatura'];
const FROTA = {};
let FROTA_MAT = null;
{
  const mat = frotaMaterial(); mat.userData.luz.value = 0.3; FROTA_MAT = mat; // carro abandonado: de dia só o reflexo; à noite lanternas e faróis acesos
  for (const k in FROTA_DADOS) {
    const D = FROTA_DADOS[k], g0 = frotaGeo(D.l0, true), g1 = frotaGeo(D.l1, true), gv = frotaGeo(D.gl, false), max = 48;
    const mk = (g, m, sh) => { const im = new THREE.InstancedMesh(g, m, max); im.count = 0; im.visible = false; im.castShadow = sh; im.receiveShadow = true; im.frustumCulled = false; im.setColorAt(0, _col.set(0xffffff)); scene.add(im); return im; };
    FROTA[k] = { D, g0, g1, gv, m0: mk(g0, mat, true), m1: mk(g1, mat, true), mv: mk(gv, FROTA_VIDRO, false) };
  }
}
let frotaModelo = [];
// o carro dirigível tem malha própria (farol que acende)
const FROTA_MEU = (() => {
  const F = FROTA.hatch, m = frotaMaterial(), g = new THREE.Group();
  const a = new THREE.Mesh(F.g0, m), v = new THREE.Mesh(F.gv, FROTA_VIDRO); a.castShadow = a.receiveShadow = true; g.add(a, v); scene.add(g); g.userData.mat = m; return g;
})();
WORLD_MESH.carBody.visible = WORLD_MESH.carCab.visible = false;
const _fm = new THREE.Matrix4(), _fc = new THREE.Color();
function frotaRender() {
  if (frotaModelo.length !== PROPS.cars.length) frotaModelo = PROPS.cars.map((c, i) => i === CAR.i ? 'hatch' : FROTA_RUA[(i * 7 + c[3] * 3) % FROTA_RUA.length]);
  for (const k in FROTA) { const F = FROTA[k]; F.m0.count = F.m1.count = F.mv.count = 0; }
  const cx = camera.position.x, cz = camera.position.z, cb = WORLD_MESH.carBody;
  for (let i = 0; i < PROPS.cars.length; i++) {
    cb.getMatrixAt(i, _fm);
    if (cb.instanceColor) cb.getColorAt(i, _fc); else _fc.set(0xffffff);
    const queimado = _fc.r + _fc.g + _fc.b < 0.2; // a explosão pinta a caixa de 0x1a1816
    if (i === CAR.i) { FROTA_MEU.matrix.copy(_fm); FROTA_MEU.matrixAutoUpdate = false; FROTA_MEU.matrixWorldNeedsUpdate = true; FROTA_MEU.children[0].material.color.set(queimado ? 0x221e1a : 0xffffff); continue; }
    const F = FROTA[frotaModelo[i]], dx = _fm.elements[12] - cx, dz = _fm.elements[14] - cz, far = dx * dx + dz * dz > 40 * 40;
    const im = far ? F.m1 : F.m0, n = im.count++;
    im.setMatrixAt(n, _fm); im.setColorAt(n, queimado ? _fc.set(0x262220) : _fc.set(0xffffff));
    if (!far && !queimado) F.mv.setMatrixAt(F.mv.count++, _fm);
  }
  for (const k in FROTA) for (const im of [FROTA[k].m0, FROTA[k].m1, FROTA[k].mv]) { im.visible = im.count > 0; if (im.count) { im.instanceMatrix.needsUpdate = true; if (im.instanceColor) im.instanceColor.needsUpdate = true; } }
  FROTA_MAT.userData.luz.value = nightF > 0.2 ? 3.2 : 0.3;
  FROTA_MEU.userData.mat.userData.luz.value = CAR.on ? (nightF > 0.2 ? 1.6 : 0.8) : 0.12;
}

