 // cabeça e pescoço
 const low=A.infected?.35:0;
 if(A.neck){A.neck.rotation.x=A.neckA+low+(clip==='idle'?Math.sin(t*.7)*.08:Math.sin(A.ph*2)*.04);A.neck.rotation.y=clip==='idle'?Math.sin(t*.45)*.35:0;}
