  const walk = (v, d) => { if (!v || typeof v !== 'object' || d > 3 || seen.has(v)) return; seen.add(v);
    if (v.isObject3D) { ref.add(v); return; } if (v.isMaterial || v.isBufferGeometry) return; for (const k in v) walk(v[k], d + 1); };
