    const px = T.fx === 1 ? PAL.xf - 5 : fx, pz = T.fx === 1 ? PAL.zc : PAL.zc + (T.fz < 0 ? 1 : -1) * (PAL.rw - 0.6);
    out.push([`${b.nome} (${A.modelo.replace(/_/g, ' ')}, ${R.estado}, ${A.pavimentos.length} pav.): fachada`, px, 1.7, pz, yaw(fx - px, fz - pz), 0.06, 1]);
