  for (let k = 0; k < n; k++) {
    const a = toCam + (R() - 0.5) * 1.2, s = 1.5 + R() * 3;
    pAdd(x, y, z, Math.sin(a) * s, R() * 2.5, Math.cos(a) * s, 1.5, idade.cor, 0.035 + R() * 0.03, 1, idade.seco);
  }
