    const fx = e.tipo === 'carro' ? e.x + Math.sin(PROPS.cars[e.ci][2]) * 1.6 : e.x, fz = e.tipo === 'carro' ? e.z + Math.cos(PROPS.cars[e.ci][2]) * 1.6 : e.z;
    if (R() < dt * (e.tipo === 'carro' ? 14 : 22)) fbAdd(fx + (R() - .5) * 0.3, (e.tipo === 'carro' ? 1.2 : 0.7), fz + (R() - .5) * 0.3, (R() - .5) * 0.5, 2 + R() * 1.5, (R() - .5) * 0.5, 0.1, 0.35 + R() * 0.3, e.st === 1 && e.tipo === 'botijao' ? 1.2 : 0.9, 1.6, 2.5, 0x1c1a18, 1, 0.8);
