    while (F.acc >= 1) { F.acc--; const a = R() * 6.28, rr = Math.sqrt(R()) * F.r; fbAdd(F.x + Math.cos(a) * rr, 0.1, F.z + Math.sin(a) * rr, 0, 1.5 + R() * 2, 0, 0.1, 0.18 + R() * 0.25 * F.r, 1.1, 1.6, 1.4, 0x1c1a18, 1, 1.2); }
