    const k = FB.t[i] / FB.life[i], dr = Math.exp(-FB.drag[i] * dt);
    FB.vx[i] *= dr; FB.vz[i] *= dr; FB.vy[i] = FB.vy[i] * dr + FB.lift[i] * dt * (FB.heat[i] > 0.2 ? 3 : 1);
    FB.x[i] += FB.vx[i] * dt + 0.4 * dt; FB.y[i] += FB.vy[i] * dt; FB.z[i] += FB.vz[i] * dt; // vento leve para leste
    if (FB.y[i] < FB.s[i] * 0.5) FB.y[i] = FB.s[i] * 0.5;
