    const gT = FB.cool[i] > 0.3 ? 0.12 : 1.4, grow = Math.min(1, FB.t[i] / gT);
    let sz = (FB.s[i] + (FB.s1[i] - FB.s[i]) * grow) * (1 + k * 1.6);
