    if (w !== i) for (const f of ['x', 'y', 'z', 'vx', 'vy', 'vz', 's', 's1', 'heat', 'cool', 't', 'life', 'col', 'seed', 'drag', 'lift']) FB[f][w] = FB[f][i];
