      txt = locked ? (bag.items.includes('chave_casa_d') ? 'E destrancar a Casa D' : 'Trancada (a chave está em alguma casa)') : `E ${d.open ? 'fechar' : 'abrir'} a porta` + (d.planks < 3 && !d.open && bag.items.includes('martelo') && bag.items.includes('tabua') && bag.items.includes('pregos') ? ' · G pregar tábua' : '') + (d.hp < d.hpMax ? ` · ${Math.ceil(d.hp)} de vida` : '');
