// mão direita do jogador armado (espelha bodyAnim: rX/rZ em colunas como no GLSL)
const _rX = (a, v) => { const c = Math.cos(a), s = Math.sin(a); return [v[0], c * v[1] - s * v[2], s * v[1] + c * v[2]]; };
