  const gait = Math.min(1.4, walkGait(Math.hypot(player.vx, player.vz)));
  const lean = 0.04 * gait + (player.crouch ? 0.25 : 0);
  q = _add(_rX(lean, _sub(q, [0, 0.95, 0])), [0, 0.95, 0]);
