  view.aim = mouse.r ? 1 : 0;
  if (wasPressed('KeyQ')) view.shoulder *= -1;
  const A = ARMAS[inv.cur];
  // distância, ombro e altura amortecidos: mirar, trocar de ombro e agachar não dão salto
  const ka = 1 - Math.exp(-dt * 12);
  view.cb = lerp(view.cb ?? 3.8, view.aim ? 1.7 : 3.8, ka); view.cs = lerp(view.cs ?? 0.9, 0.9 * view.shoulder, ka); view.cu = lerp(view.cu ?? 1.95, player.crouch ? 1.4 : 1.95, ka);
