  const rx = -fz, rz = fx;
  const cy = Math.cos(view.pitch), sy = Math.sin(view.pitch);
  const px = player.x + rx * side, pz = player.z + rz * side, py = up + (ANDARES.casaP ? player.y : 0); // dentro de casa de andares a câmera sobe com o piso
  let tx = px - fx * back * cy, ty = py + sy * back * 1.0 + 0.1, tz = pz - fz * back * cy;
  // não atravessa parede
  const dx = tx - px, dy = ty - py, dz = tz - pz, dl = Math.hypot(dx, dy, dz);
