  for (const o of [0, 0.2, -0.2]) { const h = worldRay(px + rx * o, py, pz + rz * o, dx / dl, dy / dl, dz / dl, dl); if (h) free = Math.min(free, Math.max(0.2, h.t - 0.3)); }
