  if (i >= 0) { Z.col[i] = n.cor; Z.named[i] = n.k; Z.h[i] = n.crianca ? 0.65 : Z.h[i]; Z.b[i] = n.crianca ? 0.7 : Z.b[i]; Z.age[i] = 0; Z.st[i] = 1; n.zi = i; }
  hudMsg(`${n.curto} reanimou. Reconheça pelo ${n.item.toLowerCase()}.`, 3);
