    if (R() < dt * 18) fbAdd(OBJ.fx, ROOF.h + 0.4, OBJ.fz, (R() - .5) * 0.4, 2.5, (R() - .5) * 0.4, 0.08, 0.35 + R() * 0.3, 0.15, 0.1, 5, 0xc85a5a, 0.8, 0.6);
    if (R() < dt * 30) pAdd(OBJ.fx, ROOF.h + 0.3, OBJ.fz, (R() - .5) * 2, 2 + R() * 2, (R() - .5) * 2, 0.6, 0xff4a2a, 0.04);
    if (Math.floor(OBJ.flareT) !== Math.floor(OBJ.flareT - dt)) emitNoise(OBJ.fx, OBJ.fz, 150);
    heliUpdate(dt);
