  loopSet('motor', on && CAR.on ? 0.035 + sp * 0.003 : 0, 38 + sp * 7);
  loopSet('chuva', on && rainOn ? 0.035 : 0);
  const perto = stats.bands[0] + stats.bands[1] * 0.3;
  loopSet('horda', on ? Math.min(0.16, perto * 0.0016) : 0);
  const dh = heli.visible ? Math.hypot(heli.position.x - player.x, heli.position.y - player.y, heli.position.z - player.z) : 1e9;
