window.__zw = { renderer, scene, ANDARES, andaresCasaTeste, andaresDePlantas, solidAtA, PlantasSDK, clock(t) { if (t !== undefined) dayT = t; return dayT; }, setGameT(t) { gameT = t; }, step(n, dt = 0.05) { const P = this.prof || (this.prof = {}), tm = (k, f) => { const a = performance.now(); f(); const d = performance.now() - a; P[k] = Math.max(P[k] || 0, d); }; for (let k = 0; k < n; k++) { timeU.value += dt; interactUpdate(dt); tm('player', () => playerUpdate(dt)); weaponsUpdate(dt); trailUpdate(dt); tm('fluids', () => fluidsUpdate(dt)); tm('explo', () => explosionsUpdate(dt)); tm('npc', () => npcUpdate(dt)); tm('bichos', () => bichosUpdate(dt)); tm('obj', () => objectivesUpdate(dt)); tm('horde', () => hordeUpdate(dt)); tm('corpses', () => corpsesUpdate(dt)); tm('fx', () => fxUpdate(dt, rainOn)); endInputFrame(); } }, bag, take, CONTS, DOORS, openLoot, needs, fire, ARMAS, shootRay, CALIBRES, rayZombies, worldRay, gunGroup, zSpawn, CAT, camera, view, Z, player, stats, perf, start, inv, fpsStats, CP, D, P, pile, TRAIL, POOL, zKill, zDamage, emitNoise, zAbility, solidAt, NPC, VS, ROOF, OBJ, CAR, helenaGrupo, valeRun, findFocus, FOCUS_EXT, keys, flareLight, C8, FLOORS, ZVAR, DOORS_ALL: DOORS, DIARIO, explode, EXPLO, BICHO, URUBUS, WALLP, FIRES, FB, throwItem };
