Object.assign(XPL, { ignora: false, semCol: false, inv: true, armas: true, hordaParada: false, colAgora: false });
XPL.chave('voo', 'Voo (V)', () => XPL.voo, v => { expVoo(v); return true; })
  .chave('semCol', 'Atravessar paredes andando (X)', () => XPL.semCol, v => { XPL.semCol = v; })
  .chave('inv', 'Invencível (I)', () => XPL.inv, v => { XPL.inv = v; })
  .chave('armas', 'Todas as armas, munição infinita', () => XPL.armas, v => { XPL.armas = v; })
  .chave('etiq', 'Etiquetas dos zumbis (K)', () => XPL.etiq, v => { XPL.etiq = v; })
