  if (c.zumbiRua) { const i = zSpawn(x - 4, z, CAT.lento); if (i >= 0) { Z.st[i] = 0; Z.wx[i] = x - 4; Z.wz[i] = z; Z.alertIn[i] = 0; XPL.cenZ = i; XPL.ignora = true; } }
